","/* ================================================================
 PTO Calendar — Horizon Design System themed styles
 All colors use --now-* design tokens with rgb()/rgba() wrappers
 ================================================================ */

:root {
 /* ── Surface & text aliases ── */
 --pto-surface: rgb(var(--now-color_background--primary, 255, 255, 255));
 --pto-surface-raised: rgb(var(--now-container--color, 255, 255, 255));
 --pto-surface-alt: rgb(var(--now-color_background--secondary, 245, 246, 247));
 --pto-text: rgb(var(--now-color_text--primary, 16, 23, 26));
 --pto-text-secondary: rgb(var(--now-color_text--secondary, 75, 85, 89));
 --pto-text-tertiary: rgb(var(--now-color_text--tertiary, 135, 147, 151));
 --pto-border: rgb(var(--now-container--border-color, 207, 213, 215));
 --pto-border-light: rgb(var(--now-container-card--border-color, 220, 224, 226));
 --pto-primary: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
 --pto-today-ring: rgb(var(--now-color_focus-ring, 53, 147, 37));
 --pto-hover: rgba(var(--now-actionable--primary--background-color, 0, 128, 163), 0.05);

 /* ── PTO type: Vacation (blue — primary action tokens) ── */
 --pto-vacation-bg: rgba(var(--now-actionable--primary--background-color, 0, 128, 163), 0.12);
 --pto-vacation-text: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
 --pto-vacation-border: rgba(var(--now-actionable--primary--background-color, 0, 128, 163), 0.35);

 /* ── PTO type: Sick (red — critical indicator tokens) ── */
 --pto-sick-bg: rgba(var(--now-indicator--primary_critical--background-color, 229, 34, 57), 0.12);
 --pto-sick-text: rgb(var(--now-indicator--primary_critical--background-color, 229, 34, 57));
 --pto-sick-border: rgba(var(--now-indicator--primary_critical--background-color, 229, 34, 57), 0.35);

 /* ── PTO type: Personal (green — positive indicator tokens) ── */
 --pto-personal-bg: rgba(var(--now-indicator--primary_positive--background-color, 62, 134, 0), 0.12);
 --pto-personal-text: rgb(var(--now-indicator--primary_positive--background-color, 62, 134, 0));
 --pto-personal-border: rgba(var(--now-indicator--primary_positive--background-color, 62, 134, 0), 0.35);

 /* ── PTO type: Bereavement (purple — secondary color tokens) ── */
 --pto-bereavement-bg: rgba(var(--now-color--secondary-1, 106, 27, 154), 0.12);
 --pto-bereavement-text: rgb(var(--now-color--secondary-1, 106, 27, 154));
 --pto-bereavement-border: rgba(var(--now-color--secondary-1, 106, 27, 154), 0.35);

 /* ── PTO type: Other (neutral — text-secondary tokens) ── */
 --pto-other-bg: rgba(var(--now-color_text--tertiary, 135, 147, 151), 0.12);
 --pto-other-text: rgb(var(--now-color_text--secondary, 75, 85, 89));
 --pto-other-border: rgba(var(--now-color_text--tertiary, 135, 147, 151), 0.35);
}

/* ── Base wrapper ── */
.pto-cal {
 max-width: 1200px;
 margin: 0 auto;
 padding: var(--now-static-space--xl, 1.5rem);
 font-family: var(--now-font-family, "Lato", Arial, sans-serif);
 color: var(--pto-text);
 line-height: var(--now-static-line-height, 1.25);
}

/* ── Header bar ── */
.pto-cal__header {
 display: flex;
 align-items: center;
 justify-content: space-between;
 flex-wrap: wrap;
 gap: var(--now-static-space--md, 0.75rem);
 margin-bottom: var(--now-static-space--lg, 1rem);
 padding: var(--now-static-space--lg, 1rem) var(--now-static-space--xl, 1.5rem);
 background-color: var(--pto-surface-raised);
 border: 1px solid var(--pto-border);
 border-radius: var(--now-container-card--border-radius, 8px);
 box-shadow: var(--now-static-drop-shadow--sm);
}

.pto-cal__header-left {
 display: flex;
 align-items: center;
 gap: var(--now-static-space--md, 0.75rem);
}

.pto-cal__title {
 font-size: var(--now-static-font-size--xl, 1.5rem);
 font-weight: 600;
 color: var(--pto-text);
}

.pto-cal__nav {
 display: flex;
 align-items: center;
 gap: var(--now-static-space--sm, 0.5rem);
}

/* ── Loading spinner ── */
.pto-cal__spinner {
 display: inline-block;
 width: 1.25rem;
 height: 1.25rem;
 border: 2px solid rgba(var(--now-loading_indicator--primary--color, 0, 128, 163), 0.2);
 border-top-color: rgb(var(--now-loading_indicator--primary--color, 0, 128, 163));
 border-radius: 50%;
 animation: pto-spin 0.8s linear infinite;
}

@keyframes pto-spin {
 100% { transform: rotate(360deg); }
}

/* ── Calendar grid container ── */
.pto-cal__grid {
 background-color: var(--pto-surface-raised);
 border: 1px solid var(--pto-border);
 border-radius: var(--now-container-card--border-radius, 8px);
 overflow: hidden;
 box-shadow: var(--now-static-drop-shadow--sm);
}

/* ── Weekday header row ── */
.pto-cal__weekdays {
 display: grid;
 grid-template-columns: repeat(7, 1fr);
 background-color: var(--pto-surface-alt);
 border-bottom: 1px solid var(--pto-border);
}

.pto-cal__weekday {
 padding: var(--now-static-space--md, 0.75rem) var(--now-static-space--sm, 0.5rem);
 text-align: center;
 font-weight: 600;
 font-size: var(--now-static-font-size--sm, 0.75rem);
 color: var(--pto-text-secondary);
 text-transform: uppercase;
 letter-spacing: 0.05em;
}

/* ── Week rows ── */
.pto-cal__row {
 display: grid;
 grid-template-columns: repeat(7, 1fr);
}

.pto-cal__row + .pto-cal__row {
 border-top: 1px solid var(--pto-border-light);
}

/* ── Day cells ── */
.pto-cal__cell {
 min-height: 6.5rem;
 padding: var(--now-static-space--xs, 0.25rem) var(--now-static-space--sm, 0.5rem);
 display: flex;
 flex-direction: column;
 cursor: pointer;
 transition: background-color 120ms ease;
 border-right: 1px solid var(--pto-border-light);
 position: relative;
}

.pto-cal__cell:last-child {
 border-right: none;
}

.pto-cal__cell:hover {
 background-color: var(--pto-hover);
}

.pto-cal__cell:focus-visible {
 outline: none;
 box-shadow: inset 0 0 0 2px rgb(var(--now-color_focus-ring, 53, 147, 37));
 z-index: 1;
}

/* Outside-month cells */
.pto-cal__cell--outside {
 background-color: var(--pto-surface-alt);
 cursor: default;
 opacity: 0.55;
}

.pto-cal__cell--outside:hover {
 background-color: var(--pto-surface-alt);
}

/* Today highlight */
.pto-cal__cell--today {
 background-color: rgba(var(--now-color_focus-ring, 53, 147, 37), 0.04);
}

.pto-cal__cell--today:hover {
 background-color: rgba(var(--now-color_focus-ring, 53, 147, 37), 0.08);
}

/* ── Day number ── */
.pto-cal__day-num {
 display: inline-flex;
 align-items: center;
 justify-content: center;
 width: 1.75rem;
 height: 1.75rem;
 margin: var(--now-static-space--xxs, 0.125rem) 0;
 font-size: var(--now-static-font-size--sm, 0.75rem);
 font-weight: 500;
 color: var(--pto-text);
 border-radius: 50%;
}

.pto-cal__day-num--today {
 background-color: var(--pto-today-ring);
 color: rgb(var(--now-actionable_label--primary--color, 255, 255, 255));
 font-weight: 700;
}

/* ── PTO pills within cells ── */
.pto-cal__pills {
 display: flex;
 flex-direction: column;
 gap: 2px;
 flex: 1;
 overflow: hidden;
}

.pto-pill {
 display: flex;
 align-items: center;
 gap: var(--now-static-space--xxs, 0.125rem);
 padding: 1px var(--now-static-space--xs, 0.25rem);
 border-radius: var(--now-static-border-radius--sm, 0.125rem);
 font-size: 0.6875rem;
 line-height: 1.3;
 white-space: nowrap;
 overflow: hidden;
 text-overflow: ellipsis;
 border-left: 3px solid transparent;
}

.pto-pill__dot {
 flex-shrink: 0;
 width: 6px;
 height: 6px;
 border-radius: 50%;
}

.pto-pill__text {
 overflow: hidden;
 text-overflow: ellipsis;
}

/* ── Pill color variants ── */
.pto-pill--vacation {
 background-color: var(--pto-vacation-bg);
 color: var(--pto-vacation-text);
 border-left-color: var(--pto-vacation-border);
}
.pto-pill--vacation .pto-pill__dot {
 background-color: var(--pto-vacation-text);
}

.pto-pill--sick {
 background-color: var(--pto-sick-bg);
 color: var(--pto-sick-text);
 border-left-color: var(--pto-sick-border);
}
.pto-pill--sick .pto-pill__dot {
 background-color: var(--pto-sick-text);
}

.pto-pill--personal {
 background-color: var(--pto-personal-bg);
 color: var(--pto-personal-text);
 border-left-color: var(--pto-personal-border);
}
.pto-pill--personal .pto-pill__dot {
 background-color: var(--pto-personal-text);
}

.pto-pill--bereavement {
 background-color: var(--pto-bereavement-bg);
 color: var(--pto-bereavement-text);
 border-left-color: var(--pto-bereavement-border);
}
.pto-pill--bereavement .pto-pill__dot {
 background-color: var(--pto-bereavement-text);
}

.pto-pill--other {
 background-color: var(--pto-other-bg);
 color: var(--pto-other-text);
 border-left-color: var(--pto-other-border);
}
.pto-pill--other .pto-pill__dot {
 background-color: var(--pto-other-text);
}

/* ── Overflow indicator ── */
.pto-cal__overflow {
 font-size: 0.625rem;
 color: var(--pto-text-tertiary);
 padding-left: var(--now-static-space--xs, 0.25rem);
 font-style: italic;
}

/* ── Legend ── */
.pto-cal__legend {
 display: flex;
 align-items: center;
 flex-wrap: wrap;
 gap: var(--now-static-space--md, 0.75rem);
 margin-top: var(--now-static-space--lg, 1rem);
 padding: var(--now-static-space--md, 0.75rem) var(--now-static-space--xl, 1.5rem);
 background-color: var(--pto-surface-raised);
 border: 1px solid var(--pto-border);
 border-radius: var(--now-container-card--border-radius, 8px);
 box-shadow: var(--now-static-drop-shadow--sm);
}

.pto-cal__legend-label {
 font-weight: 600;
 font-size: var(--now-static-font-size--sm, 0.75rem);
 color: var(--pto-text-secondary);
 text-transform: uppercase;
 letter-spacing: 0.05em;
}

.pto-pill--legend {
 padding: var(--now-static-space--xxs, 0.125rem) var(--now-static-space--sm, 0.5rem);
 font-size: var(--now-static-font-size--sm, 0.75rem);
 font-weight: 500;
 border-radius: var(--now-static-border-radius--md, 0.25rem);
 cursor: default;
}

/* ── Responsive ── */
@media (max-width: 900px) {
 .pto-cal {
 padding: var(--now-static-space--md, 0.75rem);
 }

 .pto-cal__header {
 flex-direction: column;
 align-items: flex-start;
 }

 .pto-cal__cell {
 min-height: 5rem;
 padding: 2px;
 }

 .pto-pill__text {
 max-width: 3rem;
 }
}

@media (max-width: 600px) {
 .pto-cal__cell {
 min-height: 3.5rem;
 }

 .pto-cal__weekday {
 font-size: 0.625rem;
 padding: var(--now-static-space--xs, 0.25rem) 0;
 }

 .pto-pill {
 font-size: 0.5625rem;
 }

 .pto-pill__dot {
 width: 4px;
 height: 4px;
 }

 .pto-cal__legend {
 gap: var(--now-static-space--sm, 0.5rem);
 }
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","import React, { useState, useEffect, useCallback, useMemo } from "react";
import { Button } from "@servicenow/react-components/Button";
import "./calendar.css";

var MONTHS = [
 "January", "February", "March", "April", "May", "June",
 "July", "August", "September", "October", "November", "December"
];

var WEEKDAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

var PTO_TYPE_CONFIG = {
 vacation: { label: "Vacation", cls: "pto-pill--vacation" },
 sick: { label: "Sick", cls: "pto-pill--sick" },
 personal: { label: "Personal", cls: "pto-pill--personal" },
 bereavement: { label: "Bereavement", cls: "pto-pill--bereavement" },
 other: { label: "Other", cls: "pto-pill--other" }
};

var TABLE = "x_165991_pto_cal_0_pto_entry";

function pad(n) { return String(n).padStart(2, "0"); }

function fmtDate(y, m, d) {
 return y + "-" + pad(m + 1) + "-" + pad(d);
}

function parseLocalDate(str) {
 var parts = str.split("-");
 return new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
}

function buildMonthCells(year, month) {
 var firstDow = new Date(year, month, 1).getDay();
 var daysInMonth = new Date(year, month + 1, 0).getDate();
 var prevDays = new Date(year, month, 0).getDate();
 var cells = [];

 for (var i = firstDow - 1; i >= 0; i--) {
 cells.push({ day: prevDays - i, inMonth: false, date: null });
 }
 for (var d = 1; d <= daysInMonth; d++) {
 cells.push({ day: d, inMonth: true, date: fmtDate(year, month, d) });
 }
 var rem = 7 - (cells.length % 7);
 if (rem < 7) {
 for (var j = 1; j <= rem; j++) {
 cells.push({ day: j, inMonth: false, date: null });
 }
 }
 return cells;
}

function buildDateMap(entries) {
 var map = {};
 entries.forEach(function (entry) {
 var startStr = entry.start_date && entry.start_date.value
 ? entry.start_date.value : entry.start_date;
 var endStr = entry.end_date && entry.end_date.value
 ? entry.end_date.value : entry.end_date;
 if (!startStr || !endStr) return;

 var cur = parseLocalDate(startStr);
 var end = parseLocalDate(endStr);

 while (cur <= end) {
 var key = fmtDate(cur.getFullYear(), cur.getMonth(), cur.getDate());
 if (!map[key]) map[key] = [];
 map[key].push(entry);
 cur.setDate(cur.getDate() + 1);
 }
 });
 return map;
}

function CalendarHeader({ month, year, loading, onPrev, onNext, onToday }) {
 return (
 <div className="pto-cal__header">
 <div className="pto-cal__header-left">
 <span className="pto-cal__title">{MONTHS[month]} {year}</span>
 {loading && <span className="pto-cal__spinner" aria-label="Loading" />}
 </div>
 <div className="pto-cal__nav">
 <Button label="‹ Prev" variant="secondary" size="md" onClicked={onPrev} />
 <Button label="Today" variant="tertiary" size="md" onClicked={onToday} />
 <Button label="Next ›" variant="secondary" size="md" onClicked={onNext} />
 </div>
 </div>
 );
}

function PtoPill({ entry }) {
 var type = entry.pto_type && entry.pto_type.value
 ? entry.pto_type.value : (entry.pto_type || "other");
 var userName = entry.user && entry.user.display_value
 ? entry.user.display_value : "Unknown";
 var status = entry.status && entry.status.display_value
 ? entry.status.display_value : "";
 var cfg = PTO_TYPE_CONFIG[type] || PTO_TYPE_CONFIG.other;
 var firstName = userName.split(" ")[0];

 return (
 <div
 className={"pto-pill " + cfg.cls}
 title={userName + " — " + cfg.label + " (" + status + ")"}
 >
 <span className="pto-pill__dot" />
 <span className="pto-pill__text">{firstName}</span>
 </div>
 );
}

function CalendarCell({ cell, todayStr, dateMap, onDateClick }) {
 var isToday = cell.date === todayStr;
 var cellEntries = cell.date ? (dateMap[cell.date] || []) : [];
 var cls = "pto-cal__cell"
 + (cell.inMonth ? "" : " pto-cal__cell--outside")
 + (isToday ? " pto-cal__cell--today" : "");

 return (
 <div
 className={cls}
 onClick={function () { if (cell.inMonth) onDateClick(cell.date); }}
 role={cell.inMonth ? "button" : undefined}
 tabIndex={cell.inMonth ? 0 : -1}
 onKeyDown={function (e) {
 if (cell.inMonth && (e.key === "Enter" || e.key === " ")) {
 e.preventDefault();
 onDateClick(cell.date);
 }
 }}
 aria-label={cell.inMonth
 ? MONTHS[new Date(cell.date).getMonth()] + " " + cell.day + ". Click to add PTO."
 : undefined}
 >
 <span className={"pto-cal__day-num" + (isToday ? " pto-cal__day-num--today" : "")}>
 {cell.day}
 </span>
 <div className="pto-cal__pills">
 {cellEntries.slice(0, 3).map(function (entry, i) {
 return <PtoPill key={i} entry={entry} />;
 })}
 {cellEntries.length > 3 && (
 <span className="pto-cal__overflow">+{cellEntries.length - 3} more</span>
 )}
 </div>
 </div>
 );
}

function Legend() {
 return (
 <div className="pto-cal__legend">
 <span className="pto-cal__legend-label">PTO Types:</span>
 {Object.keys(PTO_TYPE_CONFIG).map(function (key) {
 var cfg = PTO_TYPE_CONFIG[key];
 return (
 <span key={key} className={"pto-pill pto-pill--legend " + cfg.cls}>
 <span className="pto-pill__dot" />
 <span className="pto-pill__text">{cfg.label}</span>
 </span>
 );
 })}
 </div>
 );
}

export default function PTOCalendar() {
 var now = new Date();
 var todayStr = fmtDate(now.getFullYear(), now.getMonth(), now.getDate());

 var viewState = useState(function () {
 return { year: now.getFullYear(), month: now.getMonth() };
 });
 var view = viewState[0];
 var setView = viewState[1];

 var entriesState = useState([]);
 var entries = entriesState[0];
 var setEntries = entriesState[1];

 var loadingState = useState(false);
 var loading = loadingState[0];
 var setLoading = loadingState[1];

 useEffect(function () {
 setLoading(true);
 var y = view.year;
 var m = view.month;
 var startDate = fmtDate(y, m, 1);
 var endDate = fmtDate(y, m, new Date(y, m + 1, 0).getDate());
 var q = "start_date<=" + endDate + "^end_date>=" + startDate + "^statusNOT INcancelled";
 var url = "/api/now/table/" + TABLE
 + "?sysparm_display_value=all"
 + "&sysparm_query=" + encodeURIComponent(q)
 + "&sysparm_fields=sys_id,user,start_date,end_date,pto_type,status,hours,notes"
 + "&sysparm_limit=200";

 fetch(url, {
 headers: { "Accept": "application/json", "X-UserToken": window.g_ck }
 })
 .then(function (r) { return r.json(); })
 .then(function (data) { setEntries(data.result || []); setLoading(false); })
 .catch(function () { setEntries([]); setLoading(false); });
 }, [view.year, view.month]);

 var cells = useMemo(function () {
 return buildMonthCells(view.year, view.month);
 }, [view.year, view.month]);

 var dateMap = useMemo(function () {
 return buildDateMap(entries);
 }, [entries]);

 var weeks = useMemo(function () {
 var rows = [];
 for (var i = 0; i < cells.length; i += 7) {
 rows.push(cells.slice(i, i + 7));
 }
 return rows;
 }, [cells]);

 var goToPrev = useCallback(function () {
 setView(function (v) {
 return v.month === 0
 ? { year: v.year - 1, month: 11 }
 : { year: v.year, month: v.month - 1 };
 });
 }, []);

 var goToNext = useCallback(function () {
 setView(function (v) {
 return v.month === 11
 ? { year: v.year + 1, month: 0 }
 : { year: v.year, month: v.month + 1 };
 });
 }, []);

 var goToToday = useCallback(function () {
 var t = new Date();
 setView({ year: t.getFullYear(), month: t.getMonth() });
 }, []);

 var handleDateClick = useCallback(function (dateStr) {
 if (!dateStr) return;
 var url = "/" + TABLE + ".do?sys_id=-1&sysparm_query=start_date%3D"
 + dateStr + "%5Eend_date%3D" + dateStr;
 window.location.href = url;
 }, []);

 return (
 <div className="pto-cal">
 <CalendarHeader
 month={view.month}
 year={view.year}
 loading={loading}
 onPrev={goToPrev}
 onNext={goToNext}
 onToday={goToToday}
 />

 <div className="pto-cal__grid">
 <div className="pto-cal__weekdays">
 {WEEKDAYS.map(function (d) {
 return <div key={d} className="pto-cal__weekday">{d}</div>;
 })}
 </div>

 <div className="pto-cal__body">
 {weeks.map(function (week, wi) {
 return (
 <div key={wi} className="pto-cal__row">
 {week.map(function (cell, ci) {
 return (
 <CalendarCell
 key={ci}
 cell={cell}
 todayStr={todayStr}
 dateMap={dateMap}
 onDateClick={handleDateClick}
 />
 );
 })}
 </div>
 );
 })}
 </div>
 </div>

 <Legend />
 </div>
 );
}
